(() => {'use strict';const $=id=>document.getElementById(id),g=()=>window.gameDebug;let ready=false,pending=null;
function init(){if(ready)return;ready=true;document.body.classList.add('game-ui');const viewport=$('viewport');const health=document.createElement('button');health.id='hud-health';health.setAttribute('aria-label','Лист активного героя');health.onclick=()=>window.viewsDebug?.switchTab('hero');viewport.append(health);viewport.append($('party'),$('episode-status'),$('target-panel'),$('initiative'));const dock=document.createElement('section');dock.id='play-dock';dock.className='play-dock';dock.append($('map-hands'),document.querySelector('.turn-strip'),document.querySelector('.actions'));viewport.append(dock,$('dialogue'));const history=$('journal');history.title='Открыть хронику';history.setAttribute('aria-label','Открыть хронику');history.onclick=()=>g().journal();document.querySelector('header').append(history);const roll=document.createElement('button');roll.id='last-roll';roll.className='last-roll';roll.hidden=true;roll.onclick=details;viewport.append(roll);const d=document.createElement('dialog');d.id='roll-result';d.innerHTML='<div class="roll-heading"><b id="check-title"></b><span id="check-dc"></span></div><div class="check-body"><div id="check-die" class="check-die"></div><div><p id="check-formula"></p><strong id="check-outcome"></strong></div></div><button id="check-next" class="gold">Продолжить</button>';document.body.append(d);d.addEventListener('cancel',e=>{e.preventDefault();finish()});$('check-next').onclick=finish;render();}
function finish(){if(!pending)return;const resolve=pending;pending=null;$('roll-result').close();resolve();g().render();}
function check(r,title){if(!ready)return Promise.resolve();if(pending)return Promise.resolve();$('check-title').textContent=title;$('check-dc').textContent='Сложность '+r.dc;$('check-die').textContent=r.natural;$('check-formula').textContent='d20: '+r.values.join(' / ')+' · бонус '+(r.bonus>=0?'+':'')+r.bonus+' · итого '+r.total;$('check-outcome').textContent=r.success?'Успех':'Неудача';$('check-outcome').className=r.success?'check-success':'check-failure';return new Promise(resolve=>{pending=resolve;$('roll-result').showModal()});}
function details(){const d=$('modal');$('modal-title').textContent='Последний бросок';const p=document.createElement('pre');p.textContent=g().state.rolls?.at(-1)||'Бросков пока нет.';$('modal-body').replaceChildren(p);d.showModal();}
function render(){if(!ready||!g())return;document.body.classList.toggle('map-active',!$('map-view').hidden);const a=g().active(),health=$('hud-health');if(health){const portrait=$('party').querySelector('.member.active .portrait');health.replaceChildren();if(portrait){const clone=portrait.cloneNode(true);const originals=portrait.querySelectorAll('canvas');clone.querySelectorAll('canvas').forEach((c,i)=>c.getContext('2d').drawImage(originals[i],0,0));health.append(clone);}const copy=document.createElement('span');const name=document.createElement('b');name.textContent=a.name;const hp=document.createElement('small');hp.textContent=a.hp+' / '+a.max+' HP';const track=document.createElement('span');track.className='hp-track';const fill=document.createElement('i');fill.style.width=Math.max(0,a.hp/a.max*100)+'%';track.append(fill);copy.append(name,hp,track);health.append(copy);}const selected=g().selected;const target=selected&&(g().props.some(p=>p.x===selected.x&&p.y===selected.y)||g().all().some(p=>p.x===selected.x&&p.y===selected.y&&p.id!==g().active().id));$('target-panel').hidden=!target||!$('dialogue').hidden;const rolls=g().state.rolls||[];const b=$('last-roll');b.hidden=!rolls.length;b.textContent='⬡ Последний бросок · подробнее';document.querySelector('.roll-ledger').hidden=true;}
window.HUD={init,render,check,get pending(){return !!pending}};
})();
